function updateHeroBackdropPreview(){
 const form=$('#hero-slide-form'),preview=$('#lf44-backdrop-preview'),img=$('#lf44-backdrop-preview-image');
 if(!form||!preview||!img)return;
 const enabled=!!form.querySelector('[name="backgroundImageEnabled"]')?.checked;
 const raw=String(form.elements.backgroundImageUrl?.value||'').trim();
 const style=String(form.elements.background?.value||'escolar');
 const path=raw||HERO_BACKDROP_FILES[style]||HERO_BACKDROP_FILES.escolar;
 const safe=/^\/assets\/(?:editorial|categories|products)\/[a-z0-9_.-]+\.(?:png|webp|jpe?g|svg)$/i.test(path)||/^https:\/\/[^\s'"()\\]+$/i.test(path);
 if(safe&&enabled){if(img.getAttribute('src')!==path)img.setAttribute('src',path);img.style.opacity=String(Math.min(1,Math.max(0,Number(form.elements.backgroundImageOpacity?.value) || 0)));img.style.objectPosition=String(form.elements.backgroundImagePosition?.value||'center')+' center';preview.classList.remove('is-disabled');}
 else{img.removeAttribute('src');preview.classList.add('is-disabled');}
}
function updateHeroColorPreview(){const form=$('#hero-slide-form');if(!form)return;const preview=$('#lf40-gradient-preview');if(!preview)return;preview.style.background=`linear-gradient(115deg,${form.elements.gradientStart.value},${form.elements.gradientMid.value},${form.elements.gradientEnd.value})`;}
async function compressBrandLogo(file){
 if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Usa un PNG, JPG o WebP');
 if(file.size>2_000_000)throw Error('La imagen debe ser menor de 2 MB');
 const url=URL.createObjectURL(file);
 try{
  const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('No se pudo leer la imagen'));img.src=url;});
  const scale=Math.min(1,360/img.naturalWidth,160/img.naturalHeight),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));
  canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);
  for(const q of [.84,.7,.56]){const out=canvas.toDataURL('image/webp',q);if(out.length<=75000)return out;}
  throw Error('Imagen demasiado grande. Prueba otra más pequeña');
 }finally{URL.revokeObjectURL(url);}
}
